#!/usr/bin/env node
/**
 * Copies selected PURE helper functions and constants from gas-source/Code.gs, word for word, into
 * src/gas/classes.generated.ts — so the Azure Classes view uses exactly the Apps Script rules (names, schedules,
 * class status, filters) instead of hand-retyped copies (prompt Part B3: shared rules are derived from Code.gs).
 * Only functions with no Apps Script service calls are listed; Utilities.formatDate is provided by a small shim.
 *   npm run gen-gas      (also checked by the tests: the generated file must match Code.gs)
 */
'use strict';
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const ROOT = path.resolve(__dirname, '..');
const SRC = path.join(ROOT, 'gas-source', 'Code.gs');
const OUT = path.join(ROOT, 'src', 'gas', 'classes.generated.ts');

const FUNCTIONS = [
  'normalizeEmail_', 'extractAPSID_', 'courseHasTeacherEmail_', 'extractNilaiFromCourseName_', 'extractClassTimeFromCourseName_',
  'normalizeClassTimeText_', 'naturalCompareJs_', 'parseCourseSchedule_', 'parseClockTime_', 'inferMissingMeridiem_',
  'easternDayOfWeek_', 'easternWallTimeToDate_', 'computeAutomaticClassStatus_', 'formatLastLoginTimestamp_',
  'summarizeLastLogin_', 'normalizeLastLoginEntry_', 'resolveCountryFlag_', 'countryCodeToFlagServer_',
  'classRolesPrimary_', 'classRolesLabel_', 'classSupportGrantsAccess_', 'classAccessFor_', 'apsClassLiveBox_',
];
const CONSTANTS = [
  'LAST_LOGIN_TIMEZONE', 'LAST_LOGIN_SOURCE_ORDER', 'LAST_LOGIN_SOURCE_LABELS', 'CLASS_STATUS_COMPLETION_MINUTES',
  'CLASS_STATUS_LABELS', 'CLASS_STATUS_COLOR_CATEGORY', 'CLASS_SCHEDULE_DAY_TOKENS', 'PLACEHOLDER_PHOTO',
  'PRESENCE_ONLINE_WINDOW_MINUTES', 'NILAI_FILTER_OPTIONS', 'CLASS_TIME_FILTER_OPTIONS', 'CLASS_ROLE_RANK_', 'CLASS_ROLE_LABEL_',
];
const FORBIDDEN = /PropertiesService|SpreadsheetApp|CacheService|ScriptApp|Classroom\.|UrlFetchApp|GmailApp|MailApp|DriveApp|LockService|Session\.|AdminDirectory|AdminReports/;

/** True when a '/' at position j starts a regex literal (not division): previous non-space char is an operator/bracket or a keyword. */
function regexStart(src, j) {
  let k = j - 1; while (k >= 0 && /\s/.test(src[k])) k--;
  if (k < 0) return true;
  if ('(,=:[!&|?{};+-*%<>~^'.includes(src[k])) return true;
  const w = src.slice(Math.max(0, k - 9), k + 1).match(/[A-Za-z_$]+$/);
  return !!w && /^(return|typeof|case|do|else|in|of|void|throw|delete|new)$/.test(w[0]);
}
/** Index just after a regex literal starting at j (handles escapes and [...] classes). */
function skipRegex(src, j) {
  let inClass = false;
  for (let i = j + 1; i < src.length; i++) {
    const c = src[i];
    if (c === '\\') { i++; continue; }
    if (c === '[') inClass = true; else if (c === ']') inClass = false;
    else if (c === '/' && !inClass) return i;
    else if (c === '\n') return j; // not a regex after all
  }
  return j;
}

function extractBlock(src, startIdx) {
  // from startIdx to the end of the statement/function: balance (), {}, [] outside strings/regex-ish literals
  let depth = 0, i = startIdx, seenOpen = false, q = null;
  for (; i < src.length; i++) {
    const ch = src[i], prev = src[i - 1];
    if (q) { if (ch === q && prev !== '\\') q = null; continue; }
    if (ch === '/' && src[i + 1] === '/') { i = src.indexOf('\n', i); if (i < 0) i = src.length; continue; }
    if (ch === '/' && src[i + 1] === '*') { i = src.indexOf('*/', i) + 1; continue; }
    if (ch === '/' && regexStart(src, i)) { i = skipRegex(src, i); continue; }
    if (ch === "'" || ch === '"' || ch === '`') { q = ch; continue; }
    if (ch === '{' || ch === '(' || ch === '[') { depth++; seenOpen = true; }
    else if (ch === '}' || ch === ')' || ch === ']') { depth--; if (depth === 0 && seenOpen && ch === '}' && src.slice(startIdx, startIdx + 9) === 'function ') return src.slice(startIdx, i + 1); }
    else if (ch === ';' && depth === 0) return src.slice(startIdx, i + 1);
  }
  throw new Error('unterminated block at ' + startIdx);
}
function find(src, re, name) {
  const m = re.exec(src);
  if (!m) throw new Error('not found in Code.gs: ' + name);
  return extractBlock(src, m.index);
}

function main() {
  const src = fs.readFileSync(SRC, 'utf8');
  const parts = [];
  for (const c of CONSTANTS) parts.push(find(src, new RegExp('^(?:var|const|let) ' + c + ' = ', 'm'), c));
  for (const f of FUNCTIONS) {
    const body = find(src, new RegExp('^function ' + f.replace(/\$/g, '\\$') + '\\(', 'm'), f);
    if (FORBIDDEN.test(body)) throw new Error(f + ' uses an Apps Script service — it cannot be copied as a pure helper.');
    parts.push(body);
  }
  const md5 = crypto.createHash('md5').update(src).digest('hex');
  const out = `// @ts-nocheck
/* GENERATED by tools/gen-gas-helpers.js from gas-source/Code.gs (md5 ${md5}) — DO NOT EDIT.
 * Pure Apps Script helpers copied word for word; regenerate with \`npm run gen-gas\` after \`npm run sync-gas\`. */
/* eslint-disable */
import { Utilities } from './utilities';

${parts.join('\n\n')}

export const G: any = { ${CONSTANTS.concat(FUNCTIONS).join(', ')} };
export const SOURCE_MD5 = '${md5}';
`;
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  const changed = !fs.existsSync(OUT) || fs.readFileSync(OUT, 'utf8') !== out;
  if (process.argv.includes('--check')) {
    if (changed) { console.error('[gen-gas] src/gas/classes.generated.ts is out of date — run npm run gen-gas'); process.exit(1); }
    console.log('[gen-gas] up to date'); return;
  }
  if (changed) fs.writeFileSync(OUT, out);
  console.log('[gen-gas] ' + (changed ? 'written' : 'up to date') + ': ' + FUNCTIONS.length + ' functions, ' + CONSTANTS.length + ' constants');
}
main();
